import os
from flask import Flask
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager

db = SQLAlchemy()
login_manager = LoginManager()

def create_app():
    app = Flask(__name__)
    app.config['SECRET_KEY'] = os.urandom(24)
    app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///instagram.db'
    app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

    db.init_app(app)
    login_manager.init_app(app)
    login_manager.login_view = 'auth.login'  # Используем blueprint auth, поэтому 'auth.login'

    from .models import User  # Import здесь, чтобы избежать циклического импорта

    @login_manager.user_loader
    def load_user(user_id):
        return User.query.get(int(user_id))

    # Регистрация blueprints
    from .views import views_bp
    from .auth import auth_bp  # Импортируем blueprint auth
    app.register_blueprint(views_bp)
    app.register_blueprint(auth_bp, url_prefix='/auth') # Добавляем url_prefix

    with app.app_context():
        db.create_all()

    return app
